import{_ as e,o as r,c as a,a5 as d}from"./chunks/framework.Cooo9kuv.js";const p=JSON.parse('{"title":"手机端访问跳转 — Z-BlogPHP 多设备重定向插件","description":"","frontmatter":{"标题":"ZBlogPHP 多设备重定向插件 – 手机端访问跳转","日期":"2026-07-11T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["zblog主题插件"],"标签":["301重定向","UA检测","Z-BlogPHP","微信跳转","手机跳转","移动端适配","腾讯系全覆盖","设备重定向"]},"headers":[{"level":2,"title":"插件简介","slug":"插件简介","link":"#插件简介","children":[]},{"level":2,"title":"功能特性","slug":"功能特性","link":"#功能特性","children":[{"level":3,"title":"21 种预设设备规则","slug":"_21-种预设设备规则","link":"#_21-种预设设备规则","children":[]},{"level":3,"title":"微信 / QQ 严格匹配","slug":"微信-qq-严格匹配","link":"#微信-qq-严格匹配","children":[]},{"level":3,"title":"腾讯系全覆盖","slug":"腾讯系全覆盖","link":"#腾讯系全覆盖","children":[]},{"level":3,"title":"自定义设备规则","slug":"自定义设备规则","link":"#自定义设备规则","children":[]},{"level":3,"title":"按优先级从上到下检测","slug":"按优先级从上到下检测","link":"#按优先级从上到下检测","children":[]},{"level":3,"title":"301 永久重定向","slug":"_301-永久重定向","link":"#_301-永久重定向","children":[]},{"level":3,"title":"后台管理页面保护","slug":"后台管理页面保护","link":"#后台管理页面保护","children":[]},{"level":3,"title":"后台菜单开关","slug":"后台菜单开关","link":"#后台菜单开关","children":[]},{"level":3,"title":"卸载时清空数据","slug":"卸载时清空数据","link":"#卸载时清空数据","children":[]}]},{"level":2,"title":"使用说明","slug":"使用说明","link":"#使用说明","children":[{"level":3,"title":"第一步：安装插件","slug":"第一步-安装插件","link":"#第一步-安装插件","children":[]},{"level":3,"title":"第二步：配置跳转规则","slug":"第二步-配置跳转规则","link":"#第二步-配置跳转规则","children":[]},{"level":3,"title":"第三步：验证跳转效果","slug":"第三步-验证跳转效果","link":"#第三步-验证跳转效果","children":[]}]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":2,"title":"反馈与支持","slug":"反馈与支持","link":"#反馈与支持","children":[]},{"level":2,"title":"更新日志","slug":"更新日志","link":"#更新日志","children":[{"level":3,"title":"v1.0.0（2026-07-05）","slug":"v1-0-0-2026-07-05","link":"#v1-0-0-2026-07-05","children":[]}]}],"relativePath":"md/zblog主题插件/ZBlogPHP 多设备重定向插件 - 手机端访问跳转.md","filePath":"md/zblog主题插件/ZBlogPHP 多设备重定向插件 - 手机端访问跳转.md"}'),l={name:"md/zblog主题插件/ZBlogPHP 多设备重定向插件 - 手机端访问跳转.md"};function o(i,t,n,h,s,b){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="手机端访问跳转-—-z-blogphp-多设备重定向插件" tabindex="-1">手机端访问跳转 — Z-BlogPHP 多设备重定向插件 <a class="header-anchor" href="#手机端访问跳转-—-z-blogphp-多设备重定向插件" aria-label="Permalink to &quot;手机端访问跳转 — Z-BlogPHP 多设备重定向插件&quot;">​</a></h1><blockquote><p>根据访问设备类型自动将访客 301 重定向到不同 URL，支持手机、平板、微信内置浏览器等 21 种预设设备，可按优先级从上到下依次匹配，精准控制每种设备的跳转目标。</p></blockquote><p><strong>版本</strong>：v1.0.0<br><strong>适配</strong>：Z-BlogPHP 1.7.0+<br><strong>PHP</strong>：&gt;= 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-9.png" alt=""></p><p>本插件用于根据访客的设备类型自动执行 301 永久重定向，将不同设备的访客引导至对应的目标 URL。典型应用场景包括：将手机用户跳转到移动版网站、将微信内置浏览器用户跳转到微信专用页面、将腾讯系客户端用户跳转到适配页面等。</p><p>插件内置了 21 种常见设备的预设规则，涵盖微信、QQ、腾讯系客户端、UC 浏览器、百度浏览器、搜狗浏览器、手机浏览器、平板设备、Opera、Firefox、Edge 以及主流国产手机厂商浏览器（小米、华为、Vivo、OPPO、三星）。每种规则可独立启用并配置跳转目标 URL，支持自定义 UA 检测关键词。</p><p>检测采用从上到下的优先级机制，命中第一条匹配规则后立即执行跳转，后续规则不再检测。后台管理页面和插件自身页面自动排除，不会影响正常管理操作。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="_21-种预设设备规则" tabindex="-1">21 种预设设备规则 <a class="header-anchor" href="#_21-种预设设备规则" aria-label="Permalink to &quot;21 种预设设备规则&quot;">​</a></h3><p>插件内置以下设备检测规则，每种规则可独立启用和配置跳转目标：</p><table tabindex="0"><thead><tr><th>微信内置浏览器</th><th>MicroMessenger</th><th>是</th></tr></thead><tbody><tr><td>QQ 内置浏览器</td><td>QQ/</td><td>是</td></tr><tr><td>QQ 浏览器（腾讯）</td><td>MQQBrowser、QQBrowser</td><td>否</td></tr><tr><td>腾讯客户端</td><td>TencentTraveler、QQGameHall、QQDownload、Tencent_Video、QQLive、qqnews</td><td>否</td></tr><tr><td>QQ 空间客户端</td><td>Qzone/</td><td>否</td></tr><tr><td>UC 浏览器</td><td>UCBrowser、UCWEB、UC Browser</td><td>否</td></tr><tr><td>百度浏览器</td><td>baidubrowser、Baidu Browser、baiduboxapp</td><td>否</td></tr><tr><td>搜狗浏览器</td><td>Sogou、MetaSr、SogouMobileBrowser</td><td>否</td></tr><tr><td>手机浏览器</td><td>iPhone、iPod、Android、Mobile 等</td><td>否</td></tr><tr><td>平板设备</td><td>iPad、Tablet、PlayBook</td><td>否</td></tr><tr><td>Opera Mini / Opera</td><td>Opera Mini、OPR、Opera Mobi</td><td>否</td></tr><tr><td>Firefox 移动版</td><td>Firefox.*Mobile、FxiOS</td><td>否</td></tr><tr><td>Edge 移动版</td><td>EdgA、Edge.*Mobile、EdgiOS</td><td>否</td></tr><tr><td>360 浏览器</td><td>360se、360ee、360browser、QIHU、Qihoo</td><td>否</td></tr><tr><td>猎豹浏览器</td><td>LieBao、LBBROWSER</td><td>否</td></tr><tr><td>夸克浏览器</td><td>Quark</td><td>否</td></tr><tr><td>小米浏览器（Miui）</td><td>MiuiBrowser、XiaoMi</td><td>否</td></tr><tr><td>华为浏览器</td><td>HuaweiBrowser、HUAWEI</td><td>否</td></tr><tr><td>Vivo 浏览器</td><td>VivoBrowser</td><td>否</td></tr><tr><td>OPPO 浏览器</td><td>HeyTapBrowser、OPPO</td><td>否</td></tr><tr><td>OPPO 浏览器</td><td>HeyTapBrowser、OPPO</td><td>否</td></tr></tbody></table><h3 id="微信-qq-严格匹配" tabindex="-1">微信 / QQ 严格匹配 <a class="header-anchor" href="#微信-qq-严格匹配" aria-label="Permalink to &quot;微信 / QQ 严格匹配&quot;">​</a></h3><p>微信内置浏览器和 QQ 内置浏览器采用严格匹配策略，仅匹配 UA 中明确包含 <code>MicroMessenger</code> 或 <code>QQ/</code> 标识的请求，避免将普通手机浏览器误判为微信或 QQ 客户端。插件后台界面中这两项规则会标注”严格匹配”，UA 关键词输入框也单独锁定，不可随意修改。</p><h3 id="腾讯系全覆盖" tabindex="-1">腾讯系全覆盖 <a class="header-anchor" href="#腾讯系全覆盖" aria-label="Permalink to &quot;腾讯系全覆盖&quot;">​</a></h3><p>插件内置了从微信到 QQ 空间的完整腾讯生态链检测规则：</p><p>— 微信内置浏览器（MicroMessenger）：微信内打开链接时触发<br> — QQ 内置浏览器（QQ/）：QQ 内打开链接时触发<br> — QQ 浏览器（MQQBrowser、QQBrowser）：使用 QQ 浏览器 App 时触发<br> — 腾讯客户端（TencentTraveler、QQGameHall 等）：覆盖腾讯新闻、腾讯视频、应用宝等客户端<br> — QQ 空间客户端（Qzone/）：QQ 空间内打开链接时触发</p><p>这五条规则从上到下排列，保证微信和 QQ 优先匹配，可分别配置不同的跳转目标。</p><h3 id="自定义设备规则" tabindex="-1">自定义设备规则 <a class="header-anchor" href="#自定义设备规则" aria-label="Permalink to &quot;自定义设备规则&quot;">​</a></h3><p>除了 21 种预设设备规则，您还可以添加自定义设备类型：</p><p>— 自定义设备名称，便于后台识别管理<br> — 自定义 UA 检测关键词，支持 <code>|</code> 竖线分隔多个关键词（如 <code>MyApp|MyBrowser</code>）<br> — 自定义跳转目标 URL<br> — 自定义规则与预设规则混合排序，统一管理</p><h3 id="按优先级从上到下检测" tabindex="-1">按优先级从上到下检测 <a class="header-anchor" href="#按优先级从上到下检测" aria-label="Permalink to &quot;按优先级从上到下检测&quot;">​</a></h3><p>所有规则（预设 + 自定义）在同一表格中从上到下排列，检测时按此顺序依次匹配：</p><p>— 命中第一条启用且 URL 不为空的规则后立即执行 301 跳转，后续规则不再检测<br> — 可通过调整规则顺序来控制检测优先级，例如将微信规则放在最前面，确保微信访客优先匹配<br> — 未启用或未填写跳转 URL 的规则会被自动跳过</p><h3 id="_301-永久重定向" tabindex="-1">301 永久重定向 <a class="header-anchor" href="#_301-永久重定向" aria-label="Permalink to &quot;301 永久重定向&quot;">​</a></h3><p>插件在 PHP 层面执行 301 永久重定向，对搜索引擎友好，不会损失已有页面的收录权重。命中规则后立即发送 301 状态码并跳转，不经过 JavaScript 中转，无需前端脚本支持。</p><h3 id="后台管理页面保护" tabindex="-1">后台管理页面保护 <a class="header-anchor" href="#后台管理页面保护" aria-label="Permalink to &quot;后台管理页面保护&quot;">​</a></h3><p>插件自动排除 Z-BlogPHP 管理后台路径（<code>/zb_system/</code>、<code>/zb_users/plugin/</code>）以及插件自身的配置页面，确保后台管理操作不受跳转规则影响，避免出现登录后又被跳走的尴尬情况。</p><h3 id="后台菜单开关" tabindex="-1">后台菜单开关 <a class="header-anchor" href="#后台菜单开关" aria-label="Permalink to &quot;后台菜单开关&quot;">​</a></h3><p>插件提供「添加到顶部菜单」开关，关闭后不在 Z-BlogPHP 后台左侧导航栏显示本插件入口。适合已配置好规则不再需要频繁修改的场景，保持后台菜单整洁。</p><h3 id="卸载时清空数据" tabindex="-1">卸载时清空数据 <a class="header-anchor" href="#卸载时清空数据" aria-label="Permalink to &quot;卸载时清空数据&quot;">​</a></h3><p>提供「卸载时清空数据」开关，开启后卸载插件时会自动删除插件配置数据（包括设备规则、菜单开关状态等），避免残留无用数据。默认关闭，保护配置数据不被误删。</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 <code>mobile_redirect</code> 文件夹上传至网站 <code>zb_users/plugin/</code> 目录，进入 Z-BlogPHP 后台「插件管理」页面，找到「手机端访问跳转」并点击启用。</p><h3 id="第二步-配置跳转规则" tabindex="-1">第二步：配置跳转规则 <a class="header-anchor" href="#第二步-配置跳转规则" aria-label="Permalink to &quot;第二步：配置跳转规则&quot;">​</a></h3><p>进入后台「插件管理 — 手机端访问跳转 — 设置」页面：</p><p>— 在设备规则表格中，找到需要启用的设备类型，勾选右侧「启用」复选框<br> — 在对应行的「跳转目标 URL」输入框中填写跳转地址（如 <code>https://m.example.com</code>）<br> — 如需添加自定义设备，可在表格末尾新增行，填写设备名称、UA 关键词和跳转 URL<br> — UA 关键词支持 <code>|</code> 竖线分隔多个关键词，系统会自动构建正则匹配<br> — 点击「保存设置」按钮保存配置</p><h3 id="第三步-验证跳转效果" tabindex="-1">第三步：验证跳转效果 <a class="header-anchor" href="#第三步-验证跳转效果" aria-label="Permalink to &quot;第三步：验证跳转效果&quot;">​</a></h3><p>— 用对应设备（如手机浏览器、微信内置浏览器）访问网站前台任意页面<br> — 确认是否自动跳转到配置的目标 URL<br> — 检查浏览器地址栏或开发者工具 Network 面板，确认返回的是 301 状态码<br> — 访问后台管理页面，确认不会被跳转规则影响</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 插件执行的是 301 永久重定向，浏览器和搜索引擎会缓存跳转关系。修改规则后建议清除浏览器缓存后重新测试<br> — 跳转仅在 PHP 层面执行，访客必须正常访问网站 PHP 页面才会触发检测，不适用于纯静态 HTML 文件<br> — 检测规则按表格中从上到下的顺序执行，请确保优先级高的规则排在前面<br> — 微信（MicroMessenger）和 QQ（QQ/）采用严格匹配，UA 关键词已预设且不宜修改，避免误判<br> — 后台管理页面（<code>/zb_system/</code>、<code>/zb_users/plugin/</code>）自动排除，确保后台操作不受影响<br> — 每条规则都需要同时填写 UA 关键词和跳转 URL 并开启启用开关，三者缺一则跳过不执行<br> — 旧版本（v1.0 之前）的简单模式配置数据会在首次访问后台时自动迁移到新规则格式</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.com<br> — 作者网站：softbangong.top<br> — 邮箱：<a href="mailto:yunjuliangpin@163.com" target="_blank" rel="noreferrer">yunjuliangpin@163.com</a></p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v1-0-0-2026-07-05" tabindex="-1">v1.0.0（2026-07-05） <a class="header-anchor" href="#v1-0-0-2026-07-05" aria-label="Permalink to &quot;v1.0.0（2026-07-05）&quot;">​</a></h3><p>— 首次发布<br> — 内置 21 种预设设备检测规则，覆盖微信、QQ、UC、百度、搜狗等主流移动浏览器<br> — 腾讯生态全覆盖：微信内置浏览器、QQ 内置浏览器、QQ 浏览器、腾讯客户端、QQ 空间<br> — 支持自定义设备规则，可添加任意 UA 关键词和跳转目标<br> — 按优先级从上到下检测，命中第一条即跳转<br> — 301 永久重定向，对搜索引擎友好<br> — 后台管理页面自动排除，不影响管理操作<br> — 提供后台菜单显示开关和卸载清空数据开关<br> — JSON 配置文件存储，支持旧版配置自动迁移</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2981.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2981.html</a></p>',49)])])}const g=e(l,[["render",o]]);export{p as __pageData,g as default};
